-- Camera Setup
local cam = Instance.new("Camera")
cam.CameraType = Enum.CameraType.Scriptable
cam.CFrame = CFrame.new(Vector3.new(21, 21, 30), Vector3.new(21, 21, 0))
cam.Name = "ThumbnailCamera"
cam.FieldOfView = 70
cam.Parent = model

-- Lighting Setup
local Lighting = game:GetService("Lighting")
Lighting.ClockTime = 12
Lighting.Brightness = 0
Lighting.GlobalShadows = false
Lighting.OutdoorAmbient = Color3.new(1, 1, 1)
Lighting.Ambient = Color3.new(1, 1, 1)
Lighting.EnvironmentDiffuseScale = 0
Lighting.EnvironmentSpecularScale = 0
Lighting.ExposureCompensation = 0

-- Flat Ground Setup
local ModelMethodV2 = game:GetService("ReplicatedStorage"):WaitForChild("Model Method V2")
local Bait = ModelMethodV2:WaitForChild("2.7.4"):Clone()
Bait.Name = "Playground"
Bait.Parent = model
if Bait:IsA("Model") then
    Bait:PivotTo(CFrame.new(21, 21, -0.1)) -- Move ground slightly below image
elseif Bait:IsA("BasePart") then
    Bait.CFrame = CFrame.new(21, 21, -0.1)
end
